{
  "name": "Video Centrado Demo",
  "description": "Una aplicación simple que muestra un video de ejemplo centrado en pantalla completa sobre un fondo blanco."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useRef } from 'react';
import { Play, Pause, Volume2, VolumeX, Maximize } from 'lucide-react';

const App: React.FC = () => {
  const [isPlaying, setIsPlaying] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);

  const togglePlay = () => {
    if (videoRef.current) {
      if (isPlaying) {
        videoRef.current.pause();
      } else {
        videoRef.current.play();
      }
      setIsPlaying(!isPlaying);
    }
  };

  const toggleMute = () => {
    if (videoRef.current) {
      videoRef.current.muted = !isMuted;
      setIsMuted(!isMuted);
    }
  };

  const toggleFullScreen = () => {
    if (videoRef.current) {
      if (videoRef.current.requestFullscreen) {
        videoRef.current.requestFullscreen();
      }
    }
  };

  return (
    <div className="min-h-screen w-full bg-white flex flex-col items-center justify-center p-4 sm:p-8">

      {/* Container for the video player to keep it centered and responsive */}
      <div className="relative w-full max-w-6xl aspect-video bg-black rounded-2xl shadow-2xl overflow-hidden group">

        <video
          ref={videoRef}
          className="w-full h-full object-cover"
          src="https://storage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4"
          poster="https://storage.googleapis.com/gtv-videos-bucket/sample/images/BigBuckBunny.jpg"
          onClick={togglePlay}
          onPlay={() => setIsPlaying(true)}
          onPause={() => setIsPlaying(false)}
        >
          Tu navegador no soporta la reproducción de video.
        </video>

        {/* Custom Overlay Controls (Visible on Hover or when Paused) */}
        <div 
          className={`absolute inset-0 bg-black/30 flex items-center justify-center transition-opacity duration-300 ${isPlaying ? 'opacity-0 group-hover:opacity-100' : 'opacity-100'}`}
          onClick={togglePlay} // Click overlay to play/pause
        >
          <button 
            className="p-4 bg-white/20 backdrop-blur-sm rounded-full hover:bg-white/40 transition-transform transform hover:scale-110"
            onClick={(e) => {
              e.stopPropagation();
              togglePlay();
            }}
          >
            {isPlaying ? (
              <Pause className="w-12 h-12 text-white fill-current" />
            ) : (
              <Play className="w-12 h-12 text-white fill-current ml-2" />
            )}
          </button>
        </div>

        {/* Bottom Control Bar */}
        <div className="absolute bottom-0 left-0 right-0 p-4 bg-gradient-to-t from-black/80 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex items-center justify-between">
            <div className="flex items-center space-x-4">
                <button onClick={togglePlay} className="text-white hover:text-gray-300">
                    {isPlaying ? <Pause size={24} /> : <Play size={24} />}
                </button>
                <button onClick={toggleMute} className="text-white hover:text-gray-300">
                    {isMuted ? <VolumeX size={24} /> : <Volume2 size={24} />}
                </button>
            </div>

            <button onClick={toggleFullScreen} className="text-white hover:text-gray-300">
                <Maximize size={24} />
            </button>
        </div>
      </div>

      <div className="mt-8 text-center">
        <h1 className="text-3xl font-bold text-gray-800 tracking-tight mb-2">
          Video de Ejemplo
        </h1>
        <p className="text-gray-500 max-w-lg mx-auto">
          Un ejemplo de visualización de video centrada y responsiva utilizando React y Tailwind CSS.
        </p>
      </div>

    </div>
  );
};

