import React, { useEffect, useRef } from 'react';

const App: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  // Usamos una referencia para la posición actual para evitar re-renderizados innecesarios
  const currentScrollY = useRef(0);

  useEffect(() => {
    let animationFrameId: number;

    const animate = () => {
      // Obtenemos la posición real del scroll
      const targetScroll = window.scrollY;

      // Interpolación Lineal (Lerp) para el efecto "lento/suave"
      // 0.05 es el factor de velocidad (más bajo = más inercia/lento)
      currentScrollY.current += (targetScroll - currentScrollY.current) * 0.05;

      if (containerRef.current) {
        // Configuración de dimensiones
        const maskWidth = 400;
        const maskHeight = 200;
        const initialTop = 32; // 2rem aprox (posición inicial "bien arriba")

        // Calculamos la nueva posición superior basada en el scroll suavizado
        const topPos = initialTop + currentScrollY.current;

        // clip-path: inset(top right bottom left)
        // bottom se calcula como: 100% - (posición_top + altura_máscara)
        containerRef.current.style.clipPath = `inset(${topPos}px calc(50% - ${maskWidth / 2}px) calc(100% - ${topPos + maskHeight}px) calc(50% - ${maskWidth / 2}px)`;
      }

      animationFrameId = requestAnimationFrame(animate);
    };

    // Iniciar el loop de animación
    animate();

    return () => {
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  return (
    <div className="min-h-[300vh] w-full bg-white relative">

      {/* Texto de fondo para referencia visual */}
      <div className="absolute top-80 w-full text-center px-4 pointer-events-none opacity-20 fixed">
        <h1 className="text-9xl font-bold text-gray-900">SCROLL</h1>
      </div>

      {/* 
        Contenedor del video FIJO.
        El video siempre está en pantalla completa, pero el clip-path
        decide qué parte se muestra.
      */}
      <div 
        ref={containerRef}
        className="fixed inset-0 w-full h-full bg-black z-10 shadow-2xl pointer-events-none"
        style={{
          // Valor inicial para evitar parpadeo antes de que inicie JS
          clipPath: 'inset(32px calc(50% - 200px) calc(100% - 232px) calc(50% - 200px))',
          willChange: 'clip-path' // Optimización de rendimiento para el navegador
        }}
      >
        <video
          className="w-full h-full object-cover"
          src="https://storage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4"
          poster="https://storage.googleapis.com/gtv-videos-bucket/sample/images/BigBuckBunny.jpg"
          autoPlay
          muted
          loop
          playsInline
        />
      </div>

      <div className="fixed bottom-10 left-0 w-full text-center z-0 px-4">
        <p className="text-gray-400 text-sm">
          Haz scroll para mover la máscara con fluidez.
        </p>
      </div>

    </div>
  );
};

export default App;

