          poster="https://storage.googleapis.com/gtv-videos-bucket/sample/images/BigBuckBunny.jpg"
          autoPlay
          muted
          loop
          playsInline
        />
      </div>

      <div className="fixed bottom-10 left-0 w-full text-center z-20 px-4">
