import React, { useEffect, useRef } from 'react';

const App: React.FC = () => {
  const videoContainerRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  const currentScrollY = useRef(0);

  useEffect(() => {
    let animationFrameId: number;

    const animate = () => {
      const targetScroll = window.scrollY;

      // Interpolación muy lenta para el efecto de "peso" (0.015)
      currentScrollY.current += (targetScroll - currentScrollY.current) * 0.015;

      // 1. Mover el contenido de la web (Texto, etc.) en dirección opuesta al scroll
      // Esto simula el scroll nativo pero con nuestra inercia personalizada.
      if (contentRef.current) {
        contentRef.current.style.transform = `translate3d(0, -${currentScrollY.current}px, 0)`;
      }

      // 2. Calcular la máscara del video
      if (videoContainerRef.current) {
        const maskWidth = 400;
        const maskHeight = 200;

        // Posición base "Sticky": Queremos que se quede a 32px del tope visualmente.
        // NO sumamos currentScrollY aquí, porque si lo hacemos, el video baja y se pierde.
        let topPos = 32; 

        // Efecto de "Arrastre" (Velocity Skew):
