          <div className="flex items-center gap-2">
            <span className="text-sm md:text-lg font-medium tracking-widest">CONTENT</span>
            <Fingerprint className="w-5 h-5 opacity-50 stroke-[1.5]" />
          </div>

        </div>
      </div>

      {/* CAPA DE CONTENIDO (SCROLLABLE) */}
      <div 
        ref={contentRef}
        className="fixed inset-0 w-full h-full pointer-events-none z-0 overflow-visible"
        style={{ willChange: 'transform' }}
      >

        {/* HERO BLOCK */}
        <div className="absolute top-[15vh] w-full z-20 px-6 flex justify-center">
            <div className="flex flex-col items-center justify-center w-full max-w-[1250px]">
                <div className="flex items-end leading-none gap-4 md:gap-8">
                    <h1 className="text-[12vw] md:text-[11vw] font-black text-gray-900 tracking-tighter leading-[0.8]">
                        ALWAYS
                    </h1>
                    <div className="w-[12vw] h-[12vw] md:w-[10vw] md:h-[10vw] mb-[1vw] bg-transparent border-2 border-gray-900 rounded-lg overflow-hidden relative">
                        <img 
                        src="https://images.unsplash.com/photo-1496360938681-9a918a381294?q=80&w=800&auto=format&fit=crop" 
                        alt="Watching Eye"
                        className="w-full h-full object-cover grayscale contrast-125"
                        />
                    </div>
