            <a href="#" className="hover:opacity-70 transition-opacity">Contact</a>
            </div>

            {/* Right: CTA */}
            <div>
            <a href="#" className="text-base font-bold border-b-2 border-current pb-0.5 hover:opacity-70 transition-opacity whitespace-nowrap">
                Work with us
            </a>
            </div>
        </div>
      </nav>

      {/* CAPA DE VIDEO (FONDO FIJO) */}
      <div 
        ref={videoContainerRef}
        className="fixed inset-0 w-full h-full bg-black z-10 shadow-2xl pointer-events-none"
        style={{
          clipPath: 'inset(100vh calc(50% - 250px) calc(0vh - 300px) calc(50% - 250px))', 
          willChange: 'clip-path'
        }}
      >
        <video
