  {
    id: 5,
    name: 'ORBIT',
    category: 'DIGITAL',
    image: 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?q=80&w=2000&auto=format&fit=crop',
    className: 'mix-blend-multiply'
  },
  {
