                {/* Right Column */}
                <div className="flex flex-col items-center md:items-end gap-6 w-full md:w-1/4">
                     <Sun className="w-16 h-16 md:w-24 md:h-24 text-black stroke-1 animate-[spin_10s_linear_infinite]" />
                     <p className="text-sm font-medium text-gray-900 uppercase tracking-widest">(SCROLL)</p>
                </div>
            </div>
        </div>

        {/* SECCIÓN 2: MEDIO (InfoBar Space) */}
        <div className="absolute top-[175vh] w-full flex flex-col items-center justify-center -mt-20">
           {/* Espacio reservado para la aparición de la InfoBar */}
        </div>

        {/* SECCIÓN 3: FINAL (Video Anchor) */}
        <div className="absolute top-[270vh] w-full flex justify-center px-4">
          <div className="flex flex-col items-center justify-center w-full max-w-[1250px]">
            <div className="flex flex-wrap items-center justify-center max-w-6xl gap-x-6 gap-y-2 leading-none">
                <span className="text-6xl md:text-8xl lg:text-9xl font-black text-gray-900 tracking-tighter">
                INSPIRED
                </span>
                {/* Placeholder del video */}
                <div 
                ref={finalPlaceholderRef} 
                className="w-[120px] h-[60px] md:w-[180px] md:h-[80px] lg:w-[240px] lg:h-[110px] bg-transparent relative"
                >
                </div>
                <span className="text-6xl md:text-8xl lg:text-9xl font-black text-gray-900 tracking-tighter">
                BY
                </span>
                <span className="text-6xl md:text-8xl lg:text-9xl font-black text-gray-900 tracking-tighter">
                THE
                </span>
                <span className="text-6xl md:text-8xl lg:text-9xl font-black text-gray-900 tracking-tighter">
