                </span>
            </div>
            <p className="mt-12 text-gray-500 font-mono text-xs uppercase tracking-[0.3em]">
                Creative Direction &bull; 2024
            </p>
          </div>
        </div>

        {/* --- SECCIÓN 4: ABOUT MAIN --- */}
        <div className="absolute top-[315vh] w-full px-6 md:px-12 pb-24 pointer-events-auto flex justify-center bg-[#f5f5f5] z-10">
          <div className="w-full max-w-[1250px] mx-auto flex flex-col md:flex-row gap-12 md:gap-32">
             {/* Left: Tagline */}
