                        className="border border-gray-400 rounded-full px-12 py-3 text-xs md:text-sm font-medium tracking-widest uppercase hover:bg-black hover:border-black hover:text-white transition-colors duration-300"
                       >
                        Load More
                       </button>
                   )}
                </div>

            </div>

        </div>

      </div>

      {/* UI FLOTANTE */}
      <div className="fixed bottom-8 left-8 z-50 mix-blend-difference">
        <div className="border border-white/40 px-4 py-2 rounded-full backdrop-blur-sm">
          <p className="text-white text-[10px] font-bold tracking-[0.2em] uppercase">
            Scroll Progress
          </p>
        </div>
      </div>

    </div>
  );
};

