const App: React.FC = () => {
  const mainContainerRef = useRef<HTMLDivElement>(null);
  const videoContainerRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  const finalPlaceholderRef = useRef<HTMLDivElement>(null);
  const infoBarRef = useRef<HTMLDivElement>(null);
  const workTextRef = useRef<HTMLSpanElement>(null);
  const navRef = useRef<HTMLElement>(null);
  const currentScrollY = useRef(0);

  // Estado para controlar la visualización de más proyectos (Principal)
  const [projects, setProjects] = useState(INITIAL_PROJECTS);
  const [hasLoadedMore, setHasLoadedMore] = useState(false);

  // Estado para la galería grid inferior
  const [gridWorks, setGridWorks] = useState(GRID_WORKS);
  const [hasLoadedMoreGrid, setHasLoadedMoreGrid] = useState(false);

  const handleExploreMore = () => {
    setProjects([...INITIAL_PROJECTS, ...MORE_PROJECTS]);
    setHasLoadedMore(true);
  };

  const handleLoadMoreGrid = () => {
    setGridWorks([...GRID_WORKS, ...MORE_GRID_WORKS]);
    setHasLoadedMoreGrid(true);
  };

  useEffect(() => {
    let animationFrameId: number;

    const animate = () => {
      const targetScroll = window.scrollY;
      const windowHeight = window.innerHeight;
      const windowWidth = window.innerWidth;

      // Interpolación suave del scroll
      currentScrollY.current += (targetScroll - currentScrollY.current) * 0.1;

      // 1. Mover el contenido de la web
      if (contentRef.current) {
        contentRef.current.style.transform = `translate3d(0, -${currentScrollY.current}px, 0)`;
      }

      // Constantes de dimensiones medias
      const heightMid = 600;
      const topMid = (windowHeight - heightMid) / 2;

      // --- 2. CÁLCULO DE PROGRESO DE ANIMACIÓN ---
      // Definimos un rango específico para la animación del video.
      // Queremos que el video termine de encajar (docking) cuando llegamos a la sección "INSPIRED".
      // La sección INSPIRED está en 270vh. Restamos un poco (0.5vh) para que termine cuando esté centrada.
      const animationRange = windowHeight * 2.2; 

      // Calculamos el progreso basado en este rango, no en la altura total del documento
      const scrollProgress = Math.max(0, Math.min(currentScrollY.current / animationRange, 1));

      // --- 3. CÁLCULO DE MÁSCARA Y GEOMETRÍA DEL VIDEO ---
      if (videoContainerRef.current) {

        // Destino FINAL (End): Usamos getBoundingClientRect directamente.
        // Esto permite que si seguimos haciendo scroll pasados el rango de animación,
        // el video siga "pegado" al placeholder que se mueve hacia arriba.
        let widthEnd = 180;
        let heightEnd = 80;
        let topEnd = windowHeight - 200; 
        let leftEnd = (windowWidth - widthEnd) / 2;

        if (finalPlaceholderRef.current) {
          const rect = finalPlaceholderRef.current.getBoundingClientRect();
          topEnd = rect.top; // Posición actual en pantalla del placeholder
          leftEnd = rect.left;
          widthEnd = rect.width;
          heightEnd = rect.height;
        }

        // FASE 0 (Inicio)
        const widthStart = 500;
        const heightStart = 300;
        const topStart = windowHeight * 1.0; 
        const leftStart = (windowWidth - widthStart) / 2;

        // FASE 1 (Medio)
        const widthMid = windowWidth;
        const leftMid = 0;

        // --- LÓGICA DE "LUCES FUERA" (DARK MODE) ---
        // Usamos el mismo scrollProgress. Al llegar a 1 (final de animación),
        // distFromCenter será 0.5 -> darkness 0 -> Fondo Blanco. Correcto para la nueva sección.
        const distFromCenter = Math.abs(scrollProgress - 0.5);
        const darkness = Math.max(0, 1 - distFromCenter * 5); 

        // Colores base
        const bgVal = Math.round(245 * (1 - darkness)); // #f5f5f5 -> #000000
        const textVal = Math.round(30 + (225 * darkness)); // #1f2937 -> #ffffff

        // Aplicar colores
        if (mainContainerRef.current) {
            mainContainerRef.current.style.backgroundColor = `rgb(${bgVal}, ${bgVal}, ${bgVal})`;
        }
        if (infoBarRef.current) {
            infoBarRef.current.style.color = `rgb(${textVal}, ${textVal}, ${textVal})`;
        }
        if (navRef.current) {
            navRef.current.style.color = `rgb(${textVal}, ${textVal}, ${textVal})`;
        }

        // --- INTERPOLACIÓN DE POSICIÓN DEL VIDEO ---
        let currentTop, currentLeft, currentWidth, currentHeight;

        if (scrollProgress <= 0.5) {
          // Entrada (0% -> 50%)
          const phase = scrollProgress * 2;
          const ease = phase < 0.5 ? 2 * phase * phase : -1 + (4 - 2 * phase) * phase;

          currentTop = topStart + (topMid - topStart) * ease;
          currentLeft = leftStart + (leftMid - leftStart) * ease;
          currentWidth = widthStart + (widthMid - widthStart) * ease;
          currentHeight = heightStart + (heightMid - heightStart) * ease;
        } else {
          // Salida (50% -> 100%)
          const phase = (scrollProgress - 0.5) * 2;
          const ease = phase < 0.5 ? 2 * phase * phase : -1 + (4 - 2 * phase) * phase;

          currentTop = topMid + (topEnd - topMid) * ease;
          currentLeft = leftMid + (leftEnd - leftMid) * ease;
          currentWidth = widthMid + (widthEnd - widthMid) * ease;
          currentHeight = heightMid + (heightEnd - heightMid) * ease;
        }

        const insetTop = currentTop;
        const insetLeft = currentLeft;
        const insetRight = windowWidth - (currentLeft + currentWidth);
        const insetBottom = windowHeight - (currentTop + currentHeight);

        videoContainerRef.current.style.clipPath = `inset(${insetTop}px ${insetRight}px ${insetBottom}px ${insetLeft}px)`;

        // --- 4. CONTROL BARRA DE INFO (OPACIDAD) ---
        if (infoBarRef.current) {
            // Queremos que aparezca solo cerca del medio (0.5)
            let opacity = 1 - Math.abs(scrollProgress - 0.5) * 8;
            opacity = Math.max(0, Math.min(opacity, 1)); 

            infoBarRef.current.style.opacity = opacity.toString();

            const barTopPosition = topMid + heightMid + 24; 
            infoBarRef.current.style.top = `${barTopPosition}px`;

            const translateY = (1 - opacity) * 20;
            infoBarRef.current.style.transform = `translate3d(0, ${translateY}px, 0)`;
            infoBarRef.current.style.pointerEvents = opacity > 0.1 ? 'auto' : 'none';
        }
      }

      // --- 5. PARALLAX TEXTO WORK ---
      if (workTextRef.current) {
        // La sección empieza en 390vh
        const startOffset = windowHeight * 3.9;
        const relativeScroll = currentScrollY.current - startOffset;

        // Aplicar parallax solo cuando llegamos a la sección (Math.max(0, ...))
        // Esto evita que el texto se "cuele" por arriba antes de tiempo.
        // Factor 0.92 para que acompañe a los proyectos casi hasta el final.
        const parallaxY = Math.max(0, relativeScroll) * 0.92;

        workTextRef.current.style.transform = `translate3d(0, ${parallaxY}px, 0)`;
      }

      animationFrameId = requestAnimationFrame(animate);
    };

    animate();

    return () => {
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  // Cálculo de la altura total estimada basada en el número de proyectos
  // Base (390vh) + MainProjects + Marquee/Buffer (150vh) + GridProjects (variable)
  // Ajustamos el multiplicador por fila de grid a 120vh y añadimos un buffer de +150vh para la sección Praise
  const gridRows = Math.ceil(gridWorks.length / 2);
  const estimatedHeight = 390 + (projects.length * 90) + 150 + (gridRows * 120) + 150;

  return (
    <div 
      ref={mainContainerRef}
      className="w-full bg-[#f5f5f5] text-gray-900 font-sans selection:bg-gray-200 transition-colors duration-75"
      style={{ minHeight: `${estimatedHeight}vh` }}
    >

      {/* --- MAIN MENU (FIXED, TRANSPARENT, NO BORDER) --- */}
      <nav 
        ref={navRef}
        className="fixed top-0 left-0 w-full z-50 px-6 md:px-12 py-6 bg-transparent transition-colors duration-75"
      >
        <div className="w-full max-w-[1250px] mx-auto flex justify-between items-center">
            {/* Left: Logo */}
            <div className="flex items-center gap-2">
            <Sun className="w-6 h-6 md:w-8 md:h-8 fill-current" />
            <span className="font-black text-xl md:text-2xl tracking-tight uppercase">Henri Barrett®</span>
            </div>

            {/* Center: Links (Hidden on mobile) */}
            <div className="hidden md:flex items-center gap-8 lg:gap-12 text-base font-normal">
            <a href="#" className="hover:opacity-70 transition-opacity">About us</a>
            <a href="#" className="hover:opacity-70 transition-opacity">Work</a>
            <a href="#" className="hover:opacity-70 transition-opacity">Services</a>
            <a href="#" className="hover:opacity-70 transition-opacity">Quicklys</a>
            <a href="#" className="hover:opacity-70 transition-opacity">Contact</a>
            </div>

            {/* Right: CTA */}
            <div>
            <a href="#" className="text-base font-bold border-b-2 border-current pb-0.5 hover:opacity-70 transition-opacity whitespace-nowrap">
                Work with us
            </a>
            </div>
        </div>
      </nav>

      {/* CAPA DE VIDEO (FONDO FIJO) */}
      <div 
        ref={videoContainerRef}
        className="fixed inset-0 w-full h-full bg-black z-10 shadow-2xl pointer-events-none"
        style={{
          clipPath: 'inset(100vh calc(50% - 250px) calc(0vh - 300px) calc(50% - 250px))', 
          willChange: 'clip-path'
        }}
      >
        <video
          className="w-full h-full object-cover"
          src="https://storage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4"
          poster="https://storage.googleapis.com/gtv-videos-bucket/sample/images/BigBuckBunny.jpg"
          autoPlay
          muted
          loop
          playsInline
        />
      </div>

      {/* BARRA DE INFORMACIÓN (FIJA, APARECE EN EL MEDIO) */}
      <div 
        ref={infoBarRef}
        className="fixed w-full z-20 flex justify-center opacity-0 transition-opacity duration-75"
        style={{ willChange: 'opacity, transform, top, color' }}
      >
        <div className="flex flex-wrap items-center justify-center gap-4 md:gap-8 px-4 w-full max-w-[1250px] mx-auto">

          <div className="flex items-center gap-2">
            <span className="text-sm md:text-lg font-medium tracking-widest">CAMPAIGNS</span>
            <Sun className="w-5 h-5 opacity-50 stroke-[1.5]" />
          </div>

          <div className="flex items-center gap-2">
            <span className="text-sm md:text-lg font-medium tracking-widest">BRANDING</span>
            <Zap className="w-5 h-5 opacity-50 stroke-[1.5]" />
          </div>

