        <div className="absolute top-[70vh] w-full z-20 px-6 md:px-12 flex justify-center">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center w-full max-w-[1250px] mx-auto gap-12 md:gap-0">

                {/* Left Column */}
                <div className="flex flex-col items-center md:items-start gap-4 w-full md:w-1/4">
                    <ArrowDown className="w-16 h-16 md:w-24 md:h-24 text-black stroke-1" />
                    <div className="w-full flex flex-col items-center md:items-start">
                        <p className="text-sm font-medium text-gray-900 pb-2">Here's how we can help</p>
                        <div className="h-px bg-gray-300 w-[120px] md:w-full"></div>
                    </div>
                </div>

                {/* Middle Column */}
                <div className="flex-1 flex justify-center relative w-full">
                     <div className="absolute left-1/2 top-[-10vh] bottom-[-10vh] w-px border-l-2 border-blue-400 border-dotted -translate-x-1/2 hidden md:block opacity-60"></div>
                     <p className="text-xl md:text-3xl font-normal text-center text-gray-900 max-w-3xl bg-[#f5f5f5] px-6 py-4 relative z-10 leading-tight">
