    if (featuredCarouselRef.current) {
        const x = e.pageX - featuredCarouselRef.current.offsetLeft;
        // Factor 1.1 para reducir resistencia (se siente más ligero/rápido al arrastrar que 0.7)
        const walk = (x - startXFeatured.current) * 1.1;
        featuredCarouselRef.current.scrollLeft = scrollLeftFeatured.current - walk;
