      }

      // Constantes de dimensiones medias
      const heightMid = 600;
      const topMid = (windowHeight - heightMid) / 2;

      // --- 2. CÁLCULO DE PROGRESO DE ANIMACIÓN ---
      // Definimos un rango específico para la animación del video.
      // Queremos que el video termine de encajar (docking) cuando llegamos a la sección "INSPIRED".
      // La sección INSPIRED está en 270vh. Restamos un poco (0.5vh) para que termine cuando esté centrada.
      const animationRange = windowHeight * 2.2; 

      // Calculamos el progreso basado en este rango, no en la altura total del documento
      const scrollProgress = Math.max(0, Math.min(currentScrollY.current / animationRange, 1));

      // --- 3. CÁLCULO DE MÁSCARA Y GEOMETRÍA DEL VIDEO ---
      if (videoContainerRef.current) {

        // Destino FINAL (End): Usamos getBoundingClientRect directamente.
        // Esto permite que si seguimos haciendo scroll pasados el rango de animación,
        // el video siga "pegado" al placeholder que se mueve hacia arriba.
        let widthEnd = 180;
        let heightEnd = 80;
        let topEnd = windowHeight - 200; 
        let leftEnd = (windowWidth - widthEnd) / 2;

        if (finalPlaceholderRef.current) {
          const rect = finalPlaceholderRef.current.getBoundingClientRect();
          topEnd = rect.top; // Posición actual en pantalla del placeholder
          leftEnd = rect.left;
          widthEnd = rect.width;
          heightEnd = rect.height;
        }

        // FASE 0 (Inicio)
        const widthStart = 500;
        const heightStart = 300;
        const topStart = windowHeight * 1.0; 
        const leftStart = (windowWidth - widthStart) / 2;

        // FASE 1 (Medio)
        const widthMid = windowWidth;
        const leftMid = 0;

        // --- LÓGICA DE "LUCES FUERA" (DARK MODE) ---
        // Usamos el mismo scrollProgress. Al llegar a 1 (final de animación),
        // distFromCenter será 0.5 -> darkness 0 -> Fondo Blanco. Correcto para la nueva sección.
        const distFromCenter = Math.abs(scrollProgress - 0.5);
        const darkness = Math.max(0, 1 - distFromCenter * 5); 

        // Colores base
        const bgVal = Math.round(245 * (1 - darkness)); // #f5f5f5 -> #000000
        const textVal = Math.round(30 + (225 * darkness)); // #1f2937 -> #ffffff

        // Aplicar colores
        if (mainContainerRef.current) {
            mainContainerRef.current.style.backgroundColor = `rgb(${bgVal}, ${bgVal}, ${bgVal})`;
        }
        if (infoBarRef.current) {
            infoBarRef.current.style.color = `rgb(${textVal}, ${textVal}, ${textVal})`;
        }
        if (navRef.current) {
            navRef.current.style.color = `rgb(${textVal}, ${textVal}, ${textVal})`;
        }

        // --- INTERPOLACIÓN DE POSICIÓN DEL VIDEO ---
        let currentTop, currentLeft, currentWidth, currentHeight;

        if (scrollProgress <= 0.5) {
          // Entrada (0% -> 50%)
          const phase = scrollProgress * 2;
          const ease = phase < 0.5 ? 2 * phase * phase : -1 + (4 - 2 * phase) * phase;

          currentTop = topStart + (topMid - topStart) * ease;
          currentLeft = leftStart + (leftMid - leftStart) * ease;
          currentWidth = widthStart + (widthMid - widthStart) * ease;
          currentHeight = heightStart + (heightMid - heightStart) * ease;
        } else {
          // Salida (50% -> 100%)
          const phase = (scrollProgress - 0.5) * 2;
          const ease = phase < 0.5 ? 2 * phase * phase : -1 + (4 - 2 * phase) * phase;

          currentTop = topMid + (topEnd - topMid) * ease;
          currentLeft = leftMid + (leftEnd - leftMid) * ease;
          currentWidth = widthMid + (widthEnd - widthMid) * ease;
          currentHeight = heightMid + (heightEnd - heightMid) * ease;
        }

        const insetTop = currentTop;
        const insetLeft = currentLeft;
        const insetRight = windowWidth - (currentLeft + currentWidth);
        const insetBottom = windowHeight - (currentTop + currentHeight);

        videoContainerRef.current.style.clipPath = `inset(${insetTop}px ${insetRight}px ${insetBottom}px ${insetLeft}px)`;

        // --- 4. CONTROL BARRA DE INFO (OPACIDAD) ---
        if (infoBarRef.current) {
            // Queremos que aparezca solo cerca del medio (0.5)
            let opacity = 1 - Math.abs(scrollProgress - 0.5) * 8;
            opacity = Math.max(0, Math.min(opacity, 1)); 

            infoBarRef.current.style.opacity = opacity.toString();

            const barTopPosition = topMid + heightMid + 24; 
            infoBarRef.current.style.top = `${barTopPosition}px`;

            const translateY = (1 - opacity) * 20;
            infoBarRef.current.style.transform = `translate3d(0, ${translateY}px, 0)`;
            infoBarRef.current.style.pointerEvents = opacity > 0.1 ? 'auto' : 'none';
        }
      }

      // --- 5. PARALLAX TEXTO WORK ---
      if (workTextRef.current) {
        // La sección empieza en 390vh
        const startOffset = windowHeight * 3.9;
        const relativeScroll = currentScrollY.current - startOffset;

        // Aplicar parallax solo cuando llegamos a la sección (Math.max(0, ...))
        // Esto evita que el texto se "cuele" por arriba antes de tiempo.
        // Factor 0.92 para que acompañe a los proyectos casi hasta el final.
        const parallaxY = Math.max(0, relativeScroll) * 0.92;

        workTextRef.current.style.transform = `translate3d(0, ${parallaxY}px, 0)`;
      }

      animationFrameId = requestAnimationFrame(animate);
    };

    animate();

    return () => {
      cancelAnimationFrame(animationFrameId);
      if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
    };
  }, []);

