  };

  const handleFeaturedMouseMove = (e: React.MouseEvent) => {
    if (!isDraggingFeatured.current) return;
    e.preventDefault();
    if (featuredCarouselRef.current) {
        const x = e.pageX - featuredCarouselRef.current.offsetLeft;
        // Factor 1.1 para reducir resistencia (se siente más ligero/rápido al arrastrar que 0.7)
        const walk = (x - startXFeatured.current) * 1.1;
        featuredCarouselRef.current.scrollLeft = scrollLeftFeatured.current - walk;
    }
  };

  const scrollFeatured = (direction: 'left' | 'right') => {
    if (featuredCarouselRef.current) {
      const containerWidth = featuredCarouselRef.current.offsetWidth;
      const scrollAmount = containerWidth; // Scroll one full view (3 items)
      featuredCarouselRef.current.scrollBy({
        left: direction === 'left' ? -scrollAmount : scrollAmount,
        behavior: 'smooth'
