            const offset = (rect.top - (windowHeight / 2)) * 0.08;
            hubImageRef.current.style.transform = `translate3d(0, ${offset}px, 0)`;
         }
      }

      animationFrameId = requestAnimationFrame(animate);
    };
    animate();
    return () => cancelAnimationFrame(animationFrameId);
  }, []);

