                <a href="#" className="hover:opacity-60 transition-opacity">Services</a>
                <a href="#" className="hover:opacity-60 transition-opacity">Quicklys</a>
                <a href="#" className="hover:opacity-60 transition-opacity">Contact</a>
            </div>

