      </div>

      {/* CONTENIDO SCROLLABLE */}
      <div ref={contentRef} className="fixed inset-0 w-full h-full pointer-events-none z-20 overflow-visible">

            {/* HERO - ALIGNED TO START FOR PERFECT VERTICAL ALIGNMENT BETWEEN "A" AND "W" */}
            <div className="absolute top-[18vh] w-full px-6 flex justify-center text-black">
